// Task cards: a deterministic, bounded execution contract for one builder batch. Generated by the CLI (no AI tokens) from
// tasks.md, spec.md and plan.md, so a fresh builder reads one small file instead of the whole spec, plan and task list.
import fs from 'node:fs';
import path from 'node:path';
import { paths, posix, specDirAbs } from './state.mjs';

const MAX_LINES = 120;
const MAX_BYTES = 8 * 1024;
const MAX_ACCEPT_LINES = 40;
const read = (p) => { try { return fs.readFileSync(p, 'utf8'); } catch { return null; } };
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Lines of the spec section whose heading mentions user story `n` (US<n> or "User Story <n>"), up to the next heading of the same or a higher level. */
function storySection(lines, n) {
  const re = new RegExp(`\\b(?:US|User Story\\s*)0*${n}\\b`, 'i');
  const start = lines.findIndex((l) => /^#{1,6}\s/.test(l) && re.test(l));
  if (start < 0) return [];
  const level = lines[start].match(/^#+/)[0].length;
  let end = start + 1;
  while (end < lines.length && !(/^#{1,6}\s/.test(lines[end]) && lines[end].match(/^#+/)[0].length <= level)) end++;
  return lines.slice(start, end);
}

/** A spec line that contains `id` as a whole word, plus the indented lines that continue it. */
function idLines(lines, id) {
  const re = new RegExp(`(?<![\\w.-])${esc(id)}(?![\\w-]|\\.\\d)`);
  const out = [];
  lines.forEach((l, i) => {
    if (!re.test(l) || /^#{1,6}\s/.test(l)) return;
    out.push(l);
    for (let k = i + 1; k < lines.length && /^\s+\S/.test(lines[k]) && !/^#{1,6}\s/.test(lines[k]); k++) out.push(lines[k]);
  });
  return out;
}

/** The acceptance text the batch's tasks refer to: user-story sections and AC/FR/SC lines of spec.md (each once, capped). */
export function acceptanceFor(specText, taskTexts) {
  if (!specText) return ['(no spec.md)'];
  const lines = specText.split(/\r?\n/);
  const text = taskTexts.join('\n');
  const stories = [...new Set([...text.matchAll(/\bUS(\d+)\b/g)].map((m) => m[1]))];
  const ids = [...new Set([...text.matchAll(/\b(AC\d+(?:\.\d+)*|FR-\d+|SC-\d+)\b/g)].map((m) => m[1]))];
  const out = [];
  const seen = new Set();
  const add = (arr) => { for (const l of arr) if (!seen.has(l)) { seen.add(l); out.push(l); } };
  stories.forEach((n) => add(storySection(lines, n)));
  ids.forEach((id) => add(idLines(lines, id)));
  if (!out.length) {
    const h = lines.find((l) => /^#{1,6}\s/.test(l) && /accept|scope/i.test(l));
    return [`No acceptance ids referenced: read spec.md ${h ? `"${h.replace(/^#+\s*/, '')}"` : 'in full'}.`];
  }
  const trimmed = out.filter((l, i) => l.trim() || (out[i - 1] || '').trim()); // drop repeated blank lines
  return trimmed.length > MAX_ACCEPT_LINES ? [...trimmed.slice(0, MAX_ACCEPT_LINES), '(truncated: see spec.md)'] : trimmed;
}

/** Header and the row for `repo` of plan.md's "Repository Impact" table; [] when there is none. */
export function impactRow(planText, repo) {
  if (!planText) return [];
  const lines = planText.split(/\r?\n/);
  const at = lines.findIndex((l) => /^#{1,6}\s*Repository Impact/i.test(l));
  if (at < 0) return [];
  const rows = [];
  for (let i = at + 1; i < lines.length && !/^#{1,6}\s/.test(lines[i]); i++) if (lines[i].trim().startsWith('|')) rows.push(lines[i]);
  const cell = (l) => (l.split('|')[1] || '').replace(/[`*]/g, '').trim();
  const mine = rows.find((l) => cell(l) === repo);
  return mine ? [rows[0], rows[1] && /^\|?\s*-/.test(rows[1]) ? rows[1] : null, mine].filter(Boolean) : [];
}

const range = (refs) => (refs.length > 2 ? `${refs[0]}..${refs[refs.length - 1]}` : refs.join(', '));

export function renderCard(ctx, f, repo, batch) {
  const dir = specDirAbs(ctx, f);
  const parent = f.parent ? ctx.backlog.features.find((x) => x.id === f.parent) : null;
  const spec = dir && read(path.join(dir, 'spec.md'));
  const plan = dir && read(path.join(dir, 'plan.md'));
  const repoCfg = ctx.config.repos.find((r) => r.name === repo);
  const test = repoCfg?.commands?.test && repoCfg.commands_confirmed ? `\`${repoCfg.commands.test}\`` : 'not confirmed: do not invent one; record a question for the PM';
  const round = (f.rework || []).find((r) => !r.closed_at);
  const rel = (n) => `${f.spec_dir}/${n}`;
  const head = [
    `# Task card: ${f.id} ${f.title} (${f.kind}${parent ? `, slice of ${parent.id}` : ''}, lane ${f.lane}, stage ${f.stage}) / repo ${repo}`,
    '<!-- generated by specflow dispatch; do not edit -->',
    `Batch: ${range(batch.tasks)} (${batch.tasks.length} of ${batch.left} open in ${repo}${batch.last ? ', the last batch' : ''})`,
    `Branch: ${f.branches?.[repo] || '(not recorded)'}   Test command: ${test}`,
    round ? `Rework round ${round.n}: fix only the findings for ${repo} in verification.md; start from the files they name.` : '',
    '## Tasks (this run only)',
    ...batch.items.map((t) => `- [ ] ${t.text}`),
  ].filter(Boolean);
  const impact = impactRow(plan, repo);
  const tail = [
    ...(impact.length ? ['## Repository Impact (plan.md)', ...impact] : []),
    '## Rules',
    '- Do only the tasks above. Start from the files the tasks name; search (grep -n), then read slices; no whole-file cat.',
    '- Targeted tests, quiet reporter, failures only; the full suite once before `specflow verify run`.',
    '- Mark each finished task `[X]` in tasks.md, commit locally on the branch, then `specflow checkpoint` and return.',
    `- Not in the card? Read only the needed section of ${f.spec_dir ? `${rel('spec.md')}, ${rel('plan.md')}, ${rel('tasks.md')}` : 'the spec'}. Requirement conflict: \`specflow blocker add\`, stop.`,
  ];
  let accept = acceptanceFor(spec, batch.items.map((t) => t.text));
  const build = () => [...head, '## Acceptance (from spec.md)', ...accept, ...tail].join('\n') + '\n';
  let text = build();
  while ((text.split('\n').length - 1 > MAX_LINES || Buffer.byteLength(text) > MAX_BYTES) && accept.length > 2) {
    accept = [...accept.slice(0, -2), '(truncated: see spec.md)'];
    text = build();
  }
  return text;
}

/** Writes the card to .specflow/cache/cards/<id>-<repo>.md (overwritten per dispatch); returns its path relative to the root. */
export function writeCard(ctx, f, repo, batch) {
  const dir = path.join(paths(ctx.root).cache, 'cards');
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, `${f.id}-${repo}.md`);
  fs.writeFileSync(file, renderCard(ctx, f, repo, batch));
  return posix(path.relative(ctx.root, file));
}
